insert into shows (userId, slug, title, description, author, category, coverFileId)
     select u.id, 'the-slow-kitchen', 'The Slow Kitchen', 'Unhurried conversations about cooking the long way: stocks, ferments, breads and braises. Short episodes, one idea each, from a small kitchen in Leeds.', 'Maya Okafor', 'Arts > Food', f.id
       from users u, files f
